            sessionId,
            provider: deps.provider,
            summarize: deps.summarize,
            directory: deps.directory,
            chunkTokens: deps.chunkTokens,
            leaseHolderId: holderId,
            log: log2,
            signal,
            eligibleEndOrdinalOverride: lastOrdinal + 1,
            keepLastCompartment: true
