function isRustAuthorityDrainingError(error51) {
  let current = error51;
  for (let depth = 0;depth < 3; depth += 1) {
    if (!current || typeof current !== "object")
      break;
    const record2 = current;
    if (record2.code === "authority_draining")
      return true;
    current = record2.cause ?? record2.error ?? record2.result;
  }
  return error51 instanceof Error && error51.message.includes("authority_draining");
}

